import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { fetchEmployees } from "../services/api";
import Loader from "../components/Loader";

function List() {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    fetchEmployees().then(res => {
      setData(res);
      setLoading(false);
    });
  }, []);

  const logout = () => {
    localStorage.removeItem("auth");
    navigate("/");
  };

  if (loading) return <Loader />;

  return (
    <div className="container mt-4">
      <h2>Employee List</h2>
      <button className="btn btn-danger mb-3" onClick={logout}>Logout</button>
      <button className="btn btn-success mb-3 ms-2" onClick={() => navigate("/chart")}>
        View Chart
      </button>
      <table className="table table-bordered">
        <thead>
          <tr>
            <th>Name</th>
            <th>City</th>
            <th>Salary</th>
          </tr>
        </thead>
        <tbody>
          {data.map((emp, index) => (
            <tr key={index} onClick={() => navigate(`/details/${index}`, { state: emp })}>
              <td>{emp.name}</td>
              <td>{emp.city}</td>
              <td>{emp.salary}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
export default List;
